// Writes sitemap.xml in the root: the landing page and every available version of versions/catalog.js, each with the
// date of the last commit that changed it as lastmod. The site is static, so the file is regenerated by hand:
//   node docs/make-sitemap.mjs            (after a commit that changes the pages; then commit sitemap.xml)
import {execFileSync} from 'node:child_process';
import {readFileSync, writeFileSync} from 'node:fs';
import {dirname, join, resolve} from 'node:path';
import {fileURLToPath} from 'node:url';
import vm from 'node:vm';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const site = 'https://android.levente.net/';
const sandbox = {window: {}};
vm.runInNewContext(readFileSync(join(root, 'versions', 'catalog.js'), 'utf8'), sandbox);
const versions = sandbox.window.ANDROID_VERSIONS.filter(v => v.status === 'available');

// The landing page is index.html with its script, style, strings, catalogue and card art.
const landing = ['index.html', 'app.js', 'styles.css', 'i18n.js', 'favicon.svg', 'versions/catalog.js', 'assets'];
const lastmod = paths => execFileSync('git', ['log', '-1', '--format=%cs', '--', ...paths], {cwd: root, encoding: 'utf8'}).trim();

const pages = [{loc: site, lastmod: lastmod(landing)},
  ...versions.map(v => ({loc: site + v.url, lastmod: lastmod([v.url, 'i18n.js'])}))];
for (const page of pages) if (!/^\d{4}-\d{2}-\d{2}$/.test(page.lastmod)) throw new Error(`No commit date for ${page.loc}`);

const xml = `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${pages.map(p => `  <url>\n    <loc>${p.loc}</loc>\n    <lastmod>${p.lastmod}</lastmod>\n  </url>`).join('\n')}
</urlset>
`;
writeFileSync(join(root, 'sitemap.xml'), xml);
console.log(pages.map(p => `${p.lastmod}  ${p.loc}`).join('\n'));
